for path, rows in ((OUT + "/gaps/" + WP + ".jsonl", gaps), (OUT + "/assumptions/" + WP + ".jsonl", asms)):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with io.open(path, "w", encoding="utf-8", newline="\n") as f:
        for r in rows:
            if "gaps" in path:
                o = dict(zip(["id", "title", "source", "section", "description", "evidence", "type", "area",
                              "severity", "needed_by_wave", "legacy_ref", "owner_role", "asm", "proposed", "wp"], r))
            else:
                o = dict(zip(["id", "text", "why", "read", "gap", "applied_in", "confidence", "confirm", "impact", "wp"], r))
            f.write(json.dumps(o, ensure_ascii=False) + "\n")
    print(path, len(rows))
